      sb2_zoek: typeof sb2ZoekKlokInfo === 'function' ? sb2ZoekKlokInfo() : { aan: false },   // wv1788: nachtklussen feitenlijst + tekstindex (datum, exit, duur)   // wv1321: nachtelijke linter + manifest (datum, exitcodes, verschil-aantallen; geen paden)
      scripts_veeg: typeof scriptsVeegInfo === 'function' ? scriptsVeegInfo() : { aan: false },   // wv1311: opruimronde socev-run --veeg (exit, aantal opgeveegd; geen namen)
      ovis_kalender: typeof ovisKalenderInfo === 'function' ? ovisKalenderInfo() : { aan: false },   // wv1385: OVIS Calendar-feeds (datum, exit, duur; geen namen of URL's)
      ovis_agenda: typeof ovisAgendaInfo === 'function' ? ovisAgendaInfo() : { aan: false },   // wv1411: OVIS Calendar Google-spiegel (datum, exit, duur; geen titels)
      ovis_deadlines: typeof ovisDeadlinesInfo === 'function' ? ovisDeadlinesInfo() : { aan: false },   // wv1412: deadline-register → tijdlijn + momentopname (datum, exit, duur)
      ovis: typeof ovisInfo === 'function' ? ovisInfo() : { aan: false },   // wv979: OVIS-register (laatste dag-, nacht- en Bibliothecarisronde; aantallen, geen inhoud)
      managers: typeof managersInfo === 'function' ? managersInfo() : { aan: false },   // wv895: App Managers (managers.js in deze release? welke loopt; geen inhoud)
      tokenteller: typeof tokenteller !== 'undefined' && !!tokenteller,   // wv1742: tokenteller.js in deze release (GET /app/tokens)
      ringkaart: typeof ringkaart !== 'undefined' && !!ringkaart,   // wv888: ringkaart.js in deze release (GET /app/ringkaart)
      werkers: typeof werkersInfo === 'function' ? werkersInfo() : { aan: false },   // wv1707 (OVIS M4a): Ploeg-register (aantal werkers, laatste n8n-lezing, check-aantallen; geen namen)
      mediatheek: typeof mediatheekInfo === 'function' ? mediatheekInfo() : { aan: false },   // wv1269: App Mediatheek (aantallen, geen inhoud)
      harvester: harvesterInfo(),   // wv820: App Harvester (harvester.js in deze release? bronnen, nieuwe kaarten, laatste ronde; geen inhoud)   // wv743: mini-app Bandjes (bandjes.js in deze release? register per praktijk dicht?; geen inhoud)
      ideeen: typeof ideeenInfo === 'function' ? ideeenInfo() : { aan: false },   // wv761/wv942: App AIX (laatste lezing, catalogus, plaatsing, uur- en weekronde; geen inhoud)
      aix: typeof aixInfo === 'function' ? aixInfo() : { aan: false },   // wv942: aix.js (sleutel bruikbaar?, laatst bereikbaar, plat sinds; nooit de sleutel)
      facturen: facturenInfo(),   // wv824: Facturen-app opslag (facturen-db.js in deze release?, schema van de database; geen inhoud)
      facturen_ingang: facturenIngangInfo(),   // wv856: smalle ingang /fac (ingericht?, uit?; geen inhoud, geen gebruikers)
      intake: intakeInfo(),
      mailman: typeof mailmanInfo === 'function' ? mailmanInfo() : { aan: false },   // wv1856: OVIS MailMan (stand per postvak, laatste ronde, wachtend op Jev, tellingen; geen namen)
      pdf_lezer: pdfLezerInfo(),   // wv1431: PDF-lezer via de Claude-API (schaduw; verbruik vandaag/maand, grens, terugvallen, sleutel aanwezig?; nooit de sleutel, geen inhoud)
      scansnap: scansnapInfo(),   // wv1343: ScanSnap → Intake (aan, laatste tik als aantallen, per status; geen namen)   // wv1282: aanleverweg OVIS Intake (profielen, aantal sleutels, stukken per status, blobs; geen inhoud, geen sleutels)
      // wv349: echt=false of een /tmp-pad hieronder in productie = de server draait in een wegwerpmap (zie SERVER_ECHT)
      // Productie toont alleen home/io/jobout (Fable wv349 #4: /health is open); een proef toont alle omgeleide paden.
      server: SERVER_ECHT ? { echt: true, paden: { home: serverPaden.home, io: serverPaden.io, jobout: serverPaden.jobout } }
        : { echt: false, proefmap: SERVER_PROEF, paden: serverPaden },
      // versie = de release die NU draait (de mapnaam onder releases/, gezet door de
      // supervisor). image_versie = wat er in het image is gebakken. Verschillen de
      // twee, dan draait er uitgerolde code; zijn ze gelijk, dan draait de
      // bootstrapkopie uit het image. De uitrolworkflow leest 'versie' terug als
      // bewijs dat de nieuwe release echt is opgekomen - een geslaagde uitrol die
      // stilletjes de oude code liet draaien is anders niet van een goede te
      // onderscheiden.
      versie: process.env.RELEASE_SHA || process.env.IMAGE_SHA || 'onbekend',
      image_versie: process.env.IMAGE_SHA || 'onbekend',
      jobs: Object.keys(jobs).length, chats: Object.keys(chatSessions).length,
      // Wat een uitrol nu zou afbreken (28-9-2026). Een herstart midden in een beurt, of vlak ná een beurt maar vóór
      // n8n het resultaat ophaalde, laat het antwoord stil verdwijnen (27-9 22:42, machinekamer-executie 44316).
      // uitrol.sh wacht tot beide 0 zijn. Een onopgehaald resultaat telt hooguit 10 minuten mee.
      lopend: lopendeJobs(),
      modellen: Object.keys(MODEL_ALIASSEN),
      sync: syncInfo(), inbox: inboxInfo(), sessies: sessieInfo(),
      // de wachtrij uit de auto telt mee als lopend: een uitrol zou hem anders stil weggooien (5-10-2026)
      agents: Object.assign(agentInfo(), { wachtrij_auto: autoWachtrij.length }, { lopend: agentInfo().lopend + autoWachtrij.length }),
      offsite: offsiteInfo(),
