    const grens = grenzen[t] = Math.max(Date.parse(g[t] || 0) || nu, nu - APP_NIEUW_MAX_MS);   // wv144: ouder dan 7 dagen telt niet
    const nieuw = bronnen[t].filter(function (x) { return x > grens; });
    tabs[t] = nieuw.length;
