  Object.keys(appStaat.andersIds).forEach(function (k) { if (nu0 - appStaat.andersIds[k].t > APP_ANDERS_HERHAAL_MS) delete appStaat.andersIds[k]; });
  const ah = aid ? appSha(a.id + ':' + aid) : null;
