  const nu = Date.now(), c = appGezCache[route];
  if (c && nu - c.op < APP_GEZ_CACHE_MS) return appStuur(res, 200, Object.assign({}, c.j, { vaste_plek: false, bijgewerkt: new Date(c.op).toISOString() }));
  let r;
