    const x = fs.readFileSync(p, 'utf8');
    const gui = (/<gui\b[\s\S]*?<\/gui>/.exec(x) || [''])[0];
    const adres = (/<address>([^<]+)<\/address>/.exec(gui) || [])[1] || '';
    const sleutel = (/<apikey>([^<]+)<\/apikey>/.exec(gui) || [])[1] || '';
