        p_herkomst: (tekst(l.herkomst, 300) ? tekst(l.herkomst, 300) + ' ' : '') + '(via /smal/les)',
        p_trefwoorden: Array.isArray(l.trefwoorden) ? l.trefwoorden.slice(0, 20).map(function (w) { return String(w).slice(0, 60); }) : [],
