  const p = potAfKaartDoen(maand);
  p.meting = bankNuKort() + ': ' + (meting || 'Het mailconcept aan André staat in Gmail, met beide bestanden eraan; nakijken en versturen doe je zelf.');
  await appSbRpc('mk_voor_jou_zet', { p: p });
