// Websocket: alleen /auto/ws, als ruwe tunnel naar socev-auto (dat doet zelf de token- en kastjecontrole).
function autoProxyUpgrade(req, sock, head) {
  const weiger = function (code, tekst) {
    try { sock.end('HTTP/1.1 ' + code + ' ' + tekst + '\r\nConnection: close\r\nContent-Length: 0\r\n\r\n'); } catch (e) {}
    setTimeout(function () { try { sock.destroy(); } catch (e) {} }, 1000).unref();
  };
  sock.on('error', function () {});
  if (reqPath(req) !== '/auto/ws') return weiger(404, 'Not Found');
  if (!rolPrimair()) return weiger(409, 'Conflict');
  if (!auto.kind) return weiger(503, 'Service Unavailable');
  if (auto.tunnels >= AUTO_MAX_TUNNELS) { auto.geweigerd_vol++; return weiger(503, 'Service Unavailable'); }
  auto.tunnels++;
  let dicht = false;
  const doel = net.connect(AUTO_POORT, '127.0.0.1');
  const sluit = function () {
    if (dicht) return; dicht = true; auto.tunnels--;
    try { doel.destroy(); } catch (e) {}
    try { sock.destroy(); } catch (e) {}
  };
  sock.setTimeout(0); sock.setNoDelay(true);
  doel.setNoDelay(true);
  // Antwoordt het kind niet binnen 10 s op de handdruk, dan de tunnel sluiten (anders blijven de 8 plekken bezet).
  doel.setTimeout(10000, sluit);
  doel.once('data', function () { doel.setTimeout(0); });
  doel.on('error', sluit); sock.on('error', sluit);
  doel.on('close', sluit); sock.on('close', sluit);
  doel.on('connect', function () {
    // Requestregel en headers zoals ze binnenkwamen (Node heeft ze al geparsed en gevalideerd), behalve
    // X-Forwarded-For, die wij zelf zetten. Geen CR/LF mogelijk: die weigert de parser van Node.
    let kop = 'GET /auto/ws HTTP/1.1\r\n';
    const r = req.rawHeaders;
    for (let i = 0; i + 1 < r.length; i += 2) {
      if (r[i].toLowerCase() === 'x-forwarded-for') continue;
      kop += r[i] + ': ' + r[i + 1] + '\r\n';
    }
    kop += 'X-Forwarded-For: ' + autoXff(req) + '\r\n\r\n';
    doel.write(kop);
    if (head && head.length) doel.write(head);
    sock.pipe(doel); doel.pipe(sock);
  });
}

server.on('upgrade', function (req, sock, head) {
  try { autoProxyUpgrade(req, sock, head); }
  catch (e) { logError('auto-upgrade', e); try { sock.destroy(); } catch (e2) {} }
});

// ── Tunnel socev-olares (uitwijk stap 2, 6-10-2026) ─────────────────────────────────────────────────
// Waarom: vaste adressen n8n.huisdokter.dev en socev.huisdokter.dev die bij een uitwijk naar de VPS kunnen
// omschakelen (bouwplan uitwijk §4.4). cloudflared draait als KIND van dit proces ("alles in de huidige pod"),
// net als socev-auto, maar het overleeft een uitrol: stdout/stderr gaan rechtstreeks naar het logbestand (geen pijp,
// want een Go-programma dat naar een gebroken pijp schrijft sterft aan SIGPIPE) en server.js stopt het niet bij zijn
// eigen einde. De nieuwe server.js ziet het dan als los proces en start geen tweede; pas als dat weg is (controle
// met oplopende wachttijd, hooguit 5 min) start hij een eigen kind. Een podherstart neemt alles mee.
// Wat de tunnel doorlaat staat NIET hier maar in de tunnelconfig bij Cloudflare (remote-managed, gezet door
// tools/tunnel-inrichten.js): alleen /health/publiek en de kastjepaden naar :8080, alles anders 404.
// Het kind erft NIET de pod-omgeving: alleen TUNNEL_TOKEN (kluisnaam cloudflare_tunnel_token_olares, komt
// bij een podstart binnen) plus PATH/HOME/TZ. Het token staat nooit op de commandoregel of op schijf.
// Aan/uit: zonder token of binary geen start (reden in /health tunnel.reden_uit). Noodstop zonder uitrol: het
// bestand TUNNEL_UIT_BESTAND aanmaken en het kind stoppen (kill <tunnel.pid uit /health>); bestand weghalen zet
// hem binnen 5 min weer aan.
// Draait er al een los cloudflared-tunnelproces (van vóór een uitrol, of de overbrugging tot de eerstvolgende
// podstart, gestart door tools/tunnel-inrichten.js), dan start hier geen tweede: reden_uit noemt dan het pid.
// Alleen op kant olares (uitwijk stap 6d, review 7-10 #2): de kluis kent geen kant, dus een pod op de VPS krijgt óók
// cloudflare_tunnel_token_olares. Zonder deze regel hing die pod als tweede connector aan socev-olares en verdeelde
// Cloudflare het verkeer over twee kanten. De VPS heeft zijn eigen tunnel (cloudflared-container, socev-vps).
const TUNNEL_BIN = serverPad('tunnel_bin', process.env.TUNNEL_BIN, '/opt/data/bin/cloudflared', serverProefDeel('cloudflared'));
const TUNNEL_LOG = serverPad('tunnel_log', process.env.TUNNEL_LOG, '/opt/data/bin/tunnel.log', serverProefDeel('tunnel.log'));
const TUNNEL_UIT_BESTAND = serverPad('tunnel_uit', process.env.TUNNEL_UIT_BESTAND, '/opt/data/bin/tunnel-uit', serverProefDeel('tunnel-uit'));
const TUNNEL_METRICS_POORT = parseInt(process.env.TUNNEL_METRICS_POORT || '20241', 10);
const TUNNEL_LOG_MAX = 5 * 1024 * 1024;
const tunnel = { kind: null, starts: 0, herstarts: 0, laatste_start: null, laatste_exit: null, reden_uit: null,
  timer: null, verbindingen: null, laatste_ok: null };

// Een cloudflared-tunnelproces dat niet ons kind is (los gestart). Leest alleen /proc/<pid>/cmdline.
function tunnelLosProces() {
  let pids = [];
  try { pids = fs.readdirSync('/proc').filter(function (d) { return /^\d+$/.test(d); }); } catch (e) { return null; }
  for (const pid of pids) {
    if (tunnel.kind && String(tunnel.kind.pid) === pid) continue;
    let cmd = '';
    try { cmd = fs.readFileSync('/proc/' + pid + '/cmdline', 'utf8'); } catch (e) { continue; }
    const delen = cmd.split('\0');
    // [0] is de binary; bij een script met shebang (de toets) is dat de interpreter en staat de naam op [1].
    // 'tunnel' én 'run': een losse 'cloudflared tunnel list/info' van een agent telt niet (review 6-10).
    if (!((/cloudflared$/.test(delen[0] || '') || /cloudflared$/.test(delen[1] || '')) && delen.indexOf('tunnel') >= 0 && delen.indexOf('run') >= 0)) continue;
    // Met een ándere metrics-poort dan de onze is het niet onze tunnel (6d, review #11): zo kan de toets naast de
    // echte tunnel in de pod draaien. Zonder --metrics (of met --metrics=…) telt hij wél. Gevolg: een handmatige
    // start op Olares moet poort 20241 gebruiken (of geen --metrics), anders start hier een tweede connector.
    const m = delen.indexOf('--metrics');
    if (m >= 0 && delen[m + 1] !== '127.0.0.1:' + TUNNEL_METRICS_POORT) continue;
    return parseInt(pid, 10);
  }
  return null;
}

function tunnelStart() {
  tunnel.timer = null;
  if (tunnel.kind) return;
  // Geen herstartplanning: de kant verandert niet tijdens de levensduur van dit proces.
  if (ROL_KANT !== 'olares') {
    const reden = 'kant ' + ROL_KANT + ': geen Olares-tunnel';
    if (tunnel.reden_uit !== reden) schrijfLog(nu() + ' tunnel ' + velden({ gebeurtenis: 'niet gestart', kant: ROL_KANT }));
    tunnel.reden_uit = reden;
    return;
  }
  // Blijft pollen (hooguit elke 5 min): bestand weg = tunnel weer aan, zonder herstart (review 6-10).
  if (fs.existsSync(TUNNEL_UIT_BESTAND)) { tunnel.reden_uit = 'uitgezet (' + TUNNEL_UIT_BESTAND + ')'; tunnelPlanHerstart(); return; }
  if (!fs.existsSync(TUNNEL_BIN)) { tunnel.reden_uit = 'cloudflared ontbreekt (' + TUNNEL_BIN + ')'; return; }
  const los = tunnelLosProces();
  if (los) { tunnel.reden_uit = 'loopt als los proces (pid ' + los + ', van vóór een uitrol of de overbrugging); geen tweede gestart'; tunnelPlanHerstart(); return; }
  if (!process.env.CLOUDFLARE_TUNNEL_TOKEN_OLARES) {
    tunnel.reden_uit = 'CLOUDFLARE_TUNNEL_TOKEN_OLARES ontbreekt (kluisnaam cloudflare_tunnel_token_olares, daarna podherstart)';
    return;
  }
  tunnel.reden_uit = null;
  const env = { PATH: process.env.PATH || '/usr/local/bin:/usr/bin:/bin', HOME: HOME, TZ: process.env.TZ || 'Europe/Amsterdam',
    TUNNEL_TOKEN: process.env.CLOUDFLARE_TUNNEL_TOKEN_OLARES };
  let k, fd = null;
  try {
    tunnelRoteerLog();
    fd = fs.openSync(TUNNEL_LOG, 'a');
    k = spawn(TUNNEL_BIN, ['tunnel', '--no-autoupdate', '--metrics', '127.0.0.1:' + TUNNEL_METRICS_POORT, 'run'],
      { cwd: HOME, env: env, stdio: ['ignore', fd, fd] });
  } catch (e) {
    if (fd !== null) { try { fs.closeSync(fd); } catch (e2) {} }
    logError('tunnel-spawn', e);
    tunnel.laatste_exit = { code: null, signaal: null, fout: 'spawn', iso: new Date().toISOString() };
    tunnelPlanHerstart();
    return;
  }
  tunnel.kind = k;
  tunnel.starts++;
  tunnel.laatste_start = Date.now();
  tunnel.verbindingen = null; tunnel.laatste_ok = null;
  try { fs.closeSync(fd); } catch (e) {}   // het kind heeft zijn eigen kopie
  setTimeout(tunnelWacht, 5000).unref();   // eerste meting kort na de start, niet pas na 30 s
  k.on('error', function (e) {
    logError('tunnel-kind', e);
    if (!k.pid && tunnel.kind === k) {
      tunnel.kind = null;
      tunnel.laatste_exit = { code: null, signaal: null, fout: 'spawn', iso: new Date().toISOString() };
      tunnelPlanHerstart();
    }
  });
  k.on('exit', function (code, signaal) {
    if (tunnel.kind === k) tunnel.kind = null;
    const liep = Date.now() - (tunnel.laatste_start || Date.now());
    tunnel.laatste_exit = { code: code, signaal: signaal, liep_s: Math.round(liep / 1000), iso: new Date().toISOString() };
    schrijfLog(nu() + ' tunnel ' + velden({ gebeurtenis: 'gestopt', code: code, signaal: signaal, liep_s: tunnel.laatste_exit.liep_s }));
    if (liep > 5 * 60 * 1000) tunnel.herstarts = 0;
    tunnelPlanHerstart();
  });
}

// Roteren boven TUNNEL_LOG_MAX: kopie naar .1 en het bestand zelf leegmaken. Niet hernoemen: het kind schrijft met
// O_APPEND in hetzelfde bestand door, en na leegmaken schrijft het gewoon weer vooraan.
function tunnelRoteerLog() {
  try {
    if (fs.statSync(TUNNEL_LOG).size <= TUNNEL_LOG_MAX) return;
    fs.copyFileSync(TUNNEL_LOG, TUNNEL_LOG + '.1');
    fs.truncateSync(TUNNEL_LOG, 0);
  } catch (e) {}
}

function tunnelPlanHerstart() {
  if (tunnel.timer) return;
  const ms = AUTO_BACKOFF_MS[Math.min(tunnel.herstarts, AUTO_BACKOFF_MS.length - 1)];
  tunnel.herstarts++;
  tunnel.timer = setTimeout(tunnelStart, ms);
  tunnel.timer.unref();
}

// Elke 30 s: /ready van cloudflared (200 + readyConnections zodra er verbinding met Cloudflare is). Ook voor een los
// proces, want dat luistert op dezelfde metrics-poort.
function tunnelWacht() {
  tunnelRoteerLog();
  const r = http.get({ host: '127.0.0.1', port: TUNNEL_METRICS_POORT, path: '/ready', timeout: 3000 }, function (res) {
    let s = '';
    res.setEncoding('utf8');
    res.on('data', function (d) { if (s.length < 2000) s += d; });
    res.on('end', function () {
      let n = null;
      try { n = JSON.parse(s).readyConnections; } catch (e) {}
      tunnel.verbindingen = typeof n === 'number' ? n : null;
      if (res.statusCode === 200) tunnel.laatste_ok = Date.now();
    });
  });
  r.on('timeout', function () { r.destroy(); });
  r.on('error', function () { tunnel.verbindingen = null; });
}
setInterval(tunnelWacht, 30000).unref();

function tunnelInfo() {
  return {
    aan: !!tunnel.kind, pid: tunnel.kind ? tunnel.kind.pid : null, reden_uit: tunnel.reden_uit, starts: tunnel.starts,
    laatste_start_iso: tunnel.laatste_start ? new Date(tunnel.laatste_start).toISOString() : null,
    laatste_exit: tunnel.laatste_exit,
    // verbindingen = readyConnections van cloudflared /ready (ook van een los proces); laatste_ok_iso = laatste 200.
    verbindingen: tunnel.verbindingen,
    laatste_ok_iso: tunnel.laatste_ok ? new Date(tunnel.laatste_ok).toISOString() : null
  };
}

// ── argv-detector (wv698) ───────────────────────────────────────────────────
// WAAROM (21-10-2026, uid-scheiding fase 1b; bouwplan "Socev-gesprekken onder eigen gebruiker - sleutelscheiding" § 3.6
// en § 5 #6): /proc/<pid>/cmdline is voor elke gebruiker in de pod leesbaar (hidepid en een eigen /proc kunnen niet). Een
// sleutel die als argument aan curl e.d. wordt meegegeven, kan elk ander proces dus aflezen zolang de aanroep loopt. Deze
// detector meet wie dat doet: elke 250 ms /proc/*/cmdline van nieuwe processen (en van processen jonger dan 1 s, om een
// exec na de fork te zien; hooguit 128 kB per proces en 200 nieuwe per ronde) tegen de eigen sleutelwaarden. Het is een
// steekproef, geen meetnet: een curl van 50 ms wordt vaak gemist, wat herhaald gebeurt of lang loopt niet (Fable wv698 #2). Bij een treffer: hooguit één box-rij per (procesnaam,
// ouder-script, sleutelnaam) per dag en hooguit ARGV_DET_BOX_MAX per dag, met procesnaam, ouderketen en sleutelNAAM —
// nooit de waarde. Procesnamen en paden zijn door elk proces zelf te kiezen en gaan de box in die de machinekamer leest:
// alleen [A-Za-z0-9._+/@-] blijft staan (geen opmaak, geen regels). Meet alleen; houdt niets tegen (dat doet de hook in
// de machinekamer, /opt/data/.claude/hooks). Uit: ARGV_DETECTOR=0 of het bestand /opt/data/argv-detector-uit.
const ARGV_DET_PATROON = /KEY|TOKEN|SECRET|ROLE|SLEUTEL|WACHTWOORD|PASSWORD|SESSIE/;
const ARGV_DET_VAST = ['API_SECRET', 'N8N_API_KEY', 'N8N_MCP_TOKEN', 'SUPABASE_MCP_TOKEN', 'SUPABASE_SERVICE_ROLE', 'CLOUDFLARE_API_TOKEN',
  'TELEGRAM_SESSIE', 'TELEGRAM_API_HASH', 'CLAUDE_CODE_OAUTH_TOKEN', 'AGENT_WEBHOOK_SECRET', 'WERKKAMER_SLEUTEL_POD'];
const ARGV_DET_NIET = ['SECRETS_GELADEN'];          // kommalijst van namen, geen waarde
const ARGV_DET_JONG_MS = 1000;
const ARGV_DET_LEES_MAX = 128 * 1024;
const ARGV_DET_NIEUW_MAX = 200;
const ARGV_DET_BOX_MAX = 8;
const argvDet = { aan: false, sleutels: [], gezien: new Map(), bezig: false, ticks: 0, fouten: 0, ms_max: 0, staat: null, staatPad: null, boxPad: null, procDir: '/proc' };
function argvDetSleutels(env) {
  const perWaarde = new Map();
  Object.keys(env).forEach(function (naam) {
    if (ARGV_DET_NIET.indexOf(naam) >= 0) return;
    if (ARGV_DET_VAST.indexOf(naam) < 0 && !ARGV_DET_PATROON.test(naam)) return;
    const w = env[naam];
    if (typeof w !== 'string' || w.length < 16 || /\s/.test(w)) return;
    if (perWaarde.has(w)) perWaarde.get(w).namen.push(naam);
    else perWaarde.set(w, { namen: [naam], buf: Buffer.from(w) });
  });
  return Array.from(perWaarde.values()).map(function (s) { return { naam: s.namen.sort().join('|'), buf: s.buf }; });
}
// Hooguit ARGV_DET_LEES_MAX bytes: een proces met een cmdline van megabytes kost dan niet meer dan een gewoon proces.
async function argvDetLees(p) {
  let fh = null;
  try {
    fh = await fs.promises.open(p, 'r');
    const buf = Buffer.alloc(ARGV_DET_LEES_MAX);
    let n = 0;
    while (n < buf.length) {
      const r = await fh.read(buf, n, buf.length - n, null);
      if (!r.bytesRead) break;
      n += r.bytesRead;
    }
    return buf.subarray(0, n);
  } catch (e) { return null; }
  finally { if (fh) { try { await fh.close(); } catch (e) {} } }
}
function argvDetVeilig(s, max) { return String(s || '').replace(/[^A-Za-z0-9._+\/@-]/g, '?').slice(0, max || 40) || '?'; }
function argvDetDag(t) { return new Date(t).toLocaleString('sv-SE', { timeZone: 'Europe/Amsterdam' }).slice(0, 10); }
function argvDetStaatLaad() {
  let s = null;
  try { s = JSON.parse(fs.readFileSync(argvDet.staatPad, 'utf8')); } catch (e) {}
  if (!s || typeof s !== 'object') s = {};
  return { dag: typeof s.dag === 'string' ? s.dag : '', gemeld: Array.isArray(s.gemeld) ? s.gemeld.slice(0, 200) : [],
    box_vandaag: Number(s.box_vandaag) || 0, treffers: Array.isArray(s.treffers) ? s.treffers.slice(-500) : [] };
}
function argvDetStaatBewaar() {
  try {
    const tmp = argvDet.staatPad + '.' + process.pid + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(argvDet.staat), { mode: 0o600 });
    fs.renameSync(tmp, argvDet.staatPad);
  } catch (e) { logError('argv-detector-staat', e); }
}
// ppid en procesnaam uit /proc/<pid>/stat (naam tussen de eerste '(' en de láátste ')': een naam kan ')' bevatten)
async function argvDetStat(pid) {
  try {
    const t = await fs.promises.readFile(argvDet.procDir + '/' + pid + '/stat', 'utf8');
    const a = t.indexOf('('), b = t.lastIndexOf(')');
    return { comm: t.slice(a + 1, b), ppid: Number(t.slice(b + 2).split(' ')[1]) || 0 };
  } catch (e) { return null; }
}
// Script van een proces: argv[1] van een tolk (bash/sh/python/node/…) als dat een pad is; "-c" geeft "(<tolk> -c)".
function argvDetScript(buf) {
  const a = buf.toString('utf8').split('\0');
  const tolk = path.basename(a[0] || '');
  if (!/^(ba|da|z)?sh$|^python3?(\.\d+)?$|^node$|^perl$|^ruby$|^deno$|^bun$/.test(tolk)) return null;
  let i = 1;
  while (i < a.length && /^-/.test(a[i]) && a[i] !== '-c') i++;
  if (a[i] === '-c') return '(' + tolk + ' -c)';
  return a[i] ? argvDetVeilig(a[i], 100) : null;
}
async function argvDetOuders(pid) {
  const keten = [];
  let script = null, job = null, p = pid;
  for (let n = 0; n < 8 && p > 1; n++) {
    const st = await argvDetStat(p);
    if (!st) break;
    keten.push(argvDetVeilig(st.comm, 20));
    if (n > 0 && !script) { try { script = argvDetScript(await fs.promises.readFile(argvDet.procDir + '/' + p + '/cmdline')); } catch (e) {} }
    // welke job of sessie: alleen SOCEV_AGENT_RUN (hex) of SOCEV_SESSIE (chat-id) uit de omgeving van een voorouder;
    // de rest van die omgeving wordt niet bewaard of gelogd
    if (!job) {
      try {
        const env = (await fs.promises.readFile(argvDet.procDir + '/' + p + '/environ')).toString('latin1');
        const m = /(?:^|\0)SOCEV_AGENT_RUN=([0-9a-f]{6,32})(?:\0|$)/.exec(env) || /(?:^|\0)SOCEV_SESSIE=([A-Za-z0-9_-]{1,40})(?:\0|$)/.exec(env);
        if (m) job = m[1];
      } catch (e) {}
    }
    p = st.ppid;
  }
  return { keten: keten, script: script || '(' + (keten[1] || '?') + ')', job: job };
}
function argvDetBoxRij(t) {
  try {
    const tekst = VV().lees(argvDet.boxPad);
    const eerste = /\n## \[[a-z]{2,10}\] \d{4}-\d{2}-\d{2}/.exec(tekst);
    if (!eerste) { logError('argv-detector-box', { name: 'GeenRij', code: 'geen-rij' }); return false; }
    const tijd = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Amsterdam' }).slice(0, 16);
    const rij = '\n## [week] ' + tijd + ' — Sleutel in een opdrachtregel: ' + t.naam + ' in `' + t.comm + '` (argv-detector, automatisch)\n' +
      '- status: open\n- van: pod argv-detector (server.js, wv698; hooguit 1×/dag per proces+script+sleutel, ' + ARGV_DET_BOX_MAX + '/dag totaal)\n' +
      '- gemeten: proces `' + t.comm + '` (pid ' + t.pid + '), ouderketen `' + t.keten.join(' ← ') + '`, script `' + t.script + '`' +
      (t.job ? ', job/sessie `' + t.job + '`' : '') + '; sleutelnaam ' + t.naam + ' stond letterlijk in /proc/<pid>/cmdline (waarde niet gelogd).\n' +
      '- gevolg als er niets gebeurt: elk proces in de pod — straks ook de afgeschermde Socev-gebruiker — kan deze sleutel aflezen zolang de aanroep loopt.\n' +
      '- voorstel: de aanroep omzetten naar `mk-curl --sleutel <NAAM> …` (mk-scripts/mk-curl) of de sleutel via stdin/omgeving doorgeven; ' +
      'bouwplan sleutelscheiding § 3.6 en § 5 #6. Steekproef (korte aanroepen vaak gemist); stand: /opt/data/bin/argv-detector.json.\n';
    VV().schrijf(argvDet.boxPad, tekst.slice(0, eerste.index) + rij + tekst.slice(eerste.index));   // wv900: geen link volgen
    return true;
  } catch (e) { logError('argv-detector-box', e); return false; }
}
async function argvDetTreffer(pid, naam) {
  const nuMs = Date.now(), dag = argvDetDag(nuMs), s = argvDet.staat;
  if (s.dag !== dag) { s.dag = dag; s.gemeld = []; s.box_vandaag = 0; }
  const st = await argvDetStat(pid);
  const o = await argvDetOuders(pid);
  const t = { t: new Date(nuMs).toISOString(), naam: naam, comm: argvDetVeilig(st ? st.comm : '?', 20), pid: Number(pid), keten: o.keten, script: o.script, job: o.job };
  s.treffers.push({ t: t.t, naam: t.naam, comm: t.comm, script: t.script, job: t.job });
  s.treffers = s.treffers.filter(function (x) { return nuMs - Date.parse(x.t) < 24 * 3600 * 1000; }).slice(-500);
  const sleutel = t.comm + '|' + t.script + '|' + naam;
  if (s.gemeld.indexOf(sleutel) < 0 && s.box_vandaag < ARGV_DET_BOX_MAX && argvDetBoxRij(t)) {
    s.gemeld.push(sleutel);     // pas na een geslaagde rij: mislukt hij, dan bij de volgende treffer opnieuw (Fable wv698 #9)
    s.box_vandaag++;
  }
  schrijfLog(nu() + ' argv-detector ' + velden({ sleutel: naam, proces: t.comm, script: t.script, job: t.job || '-' }));
  argvDetStaatBewaar();
}
async function argvDetTick() {
  if (argvDet.bezig || !argvDet.aan) return;
  argvDet.bezig = true;
  const t0 = Date.now();
  try {
    const namen = await fs.promises.readdir(argvDet.procDir);
    const levend = new Set();
    let nieuw = 0;
    for (const n of namen) {
      if (n.charCodeAt(0) < 48 || n.charCodeAt(0) > 57 || !/^\d+$/.test(n)) continue;
      levend.add(n);
      let e = argvDet.gezien.get(n);
      if (e && (e.klaar || t0 - e.eerst > ARGV_DET_JONG_MS)) { e.klaar = true; continue; }
      if (!e) {
        // een stortvloed nieuwe processen (straks ook van een andere gebruiker) mag de serverloop niet ophouden:
        // de rest komt de volgende ronde (Fable wv698 #3)
        if (++nieuw > ARGV_DET_NIEUW_MAX) continue;
        e = { eerst: t0, klaar: false, gemeld: [] }; argvDet.gezien.set(n, e);
      }
      const buf = await argvDetLees(argvDet.procDir + '/' + n + '/cmdline');
      if (!buf || !buf.length) continue;
      for (const s of argvDet.sleutels) {
        if (e.gemeld.indexOf(s.naam) >= 0 || buf.indexOf(s.buf) < 0) continue;
        e.gemeld.push(s.naam);
        await argvDetTreffer(n, s.naam);
      }
    }
    for (const k of argvDet.gezien.keys()) if (!levend.has(k)) argvDet.gezien.delete(k);
  } catch (err) { argvDet.fouten++; if (argvDet.fouten <= 3) logError('argv-detector', err); }
  argvDet.ticks++;
  argvDet.ms_max = Math.max(argvDet.ms_max, Date.now() - t0);
  argvDet.bezig = false;
}
function argvDetStart(o) {
  o = o || {};
  if (argvDet.aan) return;
  argvDet.sleutels = argvDetSleutels(o.env || process.env);
  argvDet.staatPad = o.staatPad; argvDet.boxPad = o.boxPad; argvDet.procDir = o.procDir || '/proc';
  argvDet.staat = argvDetStaatLaad();
  argvDet.aan = true;
  argvDet.timer = setInterval(argvDetTick, o.intervalMs || 250);
  if (argvDet.timer.unref) argvDet.timer.unref();
}
function argvDetInfo(o) {
  if (!argvDet.aan) return { aan: false };
  const nu = Date.now(), s = argvDet.staat, per = {};
  const recent = s.treffers.filter(function (x) { return nu - Date.parse(x.t) < 24 * 3600 * 1000; });
  recent.forEach(function (x) { per[x.naam] = (per[x.naam] || 0) + 1; });
  // /health is zonder sleutel bereikbaar: geen sleutelnamen, tijden of scripts (Fable wv698 #8); detail in de staat (0600)
  if (!o || !o.detail) return { aan: true, treffers_24u: recent.length, ticks: argvDet.ticks, ms_max: argvDet.ms_max, fouten: argvDet.fouten };
  return { aan: true, sleutels: argvDet.sleutels.length, treffers_24u: recent.length, per_sleutel_24u: per,
    laatste_iso: recent.length ? recent[recent.length - 1].t : null, box_vandaag: s.dag === argvDetDag(nu) ? s.box_vandaag : 0,
    ticks: argvDet.ticks, ms_max: argvDet.ms_max, fouten: argvDet.fouten };
}
// ── einde argv-detector
// Start: alleen de echte server (SERVER_ECHT); uit met ARGV_DETECTOR=0 of het bestand /opt/data/argv-detector-uit.
function argvDetectorStart() {
  if (SERVER_ECHT !== true || process.env.ARGV_DETECTOR === '0') return;
  try { if (fs.existsSync(path.join(SERVER_ECHTE_HOME, 'argv-detector-uit'))) return; } catch (e) {}
  try {
    argvDetStart({ env: process.env, staatPad: path.join(HOME, 'bin', 'argv-detector.json'),
      boxPad: path.join(VAULT, '00_Systeem', 'Meldingen', 'machinekamer.md') });
  } catch (e) { logError('argv-detector-start', e); }
}

if (process.env.AUTO_UIT_POD !== '1') { try { autoStart(); } catch (e) { logError('auto-start', e); } }
if (process.env.TUNNEL_UIT_POD !== '1') { try { tunnelStart(); } catch (e) { logError('tunnel-start', e); } }

try { geminiVoorbereiden(); } catch (e) { logError('gemini-voorbereiden', e); }
agyVersieMeten();

if (!SERVER_ECHT) {
  const omgeleid = Object.keys(serverPaden).filter(function (k) { return serverPaden[k].indexOf(SERVER_PROEF + path.sep) === 0; });
  // Proefmappen van eerdere proeven waarvan het proces niet meer leeft en die een uur stil staan: weg (toetsen stoppen
  // hun server met SIGKILL, dus opruimen bij het afsluiten kan niet). Alleen socev-app-proef-<getal> naast de eigen map.
  let opgeruimd = 0;
  try {
    const ouder = path.dirname(SERVER_PROEF);
    fs.readdirSync(ouder).forEach(function (n) {
      const m = /^socev-app-proef-(\d+)$/.exec(n);
      if (!m || Number(m[1]) === process.pid) return;
      try { process.kill(Number(m[1]), 0); return; } catch (e) { if (!e || e.code !== 'ESRCH') return; }
      const p = path.join(ouder, n);
      try { if (Date.now() - fs.lstatSync(p).mtimeMs < 60 * 60 * 1000) return; fs.rmSync(p, { recursive: true, force: true }); opgeruimd++; } catch (e) {}
    });
  } catch (e) {}
  schrijfLog(nu() + ' proefserver ' + velden({ map: SERVER_PROEF, omgeleid: omgeleid.join(',') || 'niets', oude_proefmappen_weg: opgeruimd }));
}

try { appWeesVasthouden(); } catch (e) { logError('app-wees-vast', e); }   // wv722: vóór listen, dus vóór elke /run of app-beurt
server.listen(PORT, '0.0.0.0', function () {
  console.log('claude-api v2 (async, chat-sessies, per-chat serieel, multi-workspace, modelkanaal, liveness-watchdog, achtergrondagents, breinen claude|codex|gemini) luistert op :' + PORT +
    ' (vault=' + VAULT + ', repo=' + REPO + ')');
  bewakerStart();
  argvDetectorStart();
});

// wv701 (21-10-2026, akkoord David): levensbewaking. bewaker.js draait als los proces naast deze server en laat hem doden
// als /health/publiek 3 minuten niet antwoordt; de supervisor herstart hem dan. Een worker_thread hier zou bij een dichte
// event loop of een vastgelopen proces niet betrouwbaar zijn. Alleen de echte server (SERVER_ECHT); BEWAKER=0 zet hem uit.
// Waarom en hoe: kop van bewaker.js en het bouwplan "Levensbewaking server.js (bouwplan 21-10-2026)".
function bewakerStart() {
  if (SERVER_ECHT !== true || process.env.BEWAKER === '0') return;
  const p = path.join(__dirname, 'bewaker.js');
  if (!fs.existsSync(p)) return;   // release zonder bewaker (oude uitrol.sh of terugrol)
  try { bewakerPid = require(p).start({ serverPid: process.pid, poort: PORT }); }
  catch (e) { logError('bewaker', e); }
}
